type ApiHandler = (context: AuthContext) => Promise<NextResponse | Response>;

/**
 * Higher-order function to wrap API route handlers with authentication checks.
 * @param handler - The API route handler function.
 * @param options - Options to specify authentication requirements (e.g., requireAdmin).
 * @returns A Next.js API route handler.
 */
export const withAuth = (handler: ApiHandler, options: ApiHandlerOptions = {}) => {
  return async (request: NextRequest, context?: { params: Promise<{ [key: string]: string }> | { [key: string]: string } }) => {
    try {
      const authorization = request.headers.get('Authorization');
      if (!authorization?.startsWith('Bearer ')) {
        return handleApiError({ message: 'Unauthorized: Missing token' }, 401);
      }
      const token = authorization.substring(7);
      const decodedToken = await adminAuth.verifyIdToken(token, true);

      if (!decodedToken || !decodedToken.uid) {
        return handleApiError({ message: 'Unauthorized: Invalid token' }, 401);
      }

      const user = await getUserProfile(decodedToken.uid);
      if (!user) {
        return handleApiError({ message: 'Forbidden: User profile not found' }, 403);
      }

      if (options.requireAdmin && user.role !== 'admin') {
        return handleApiError({ message: 'Forbidden: Admin access required' }, 403);
      }

      // Handle Next.js 15 async params
      const params = context?.params ? (context.params instanceof Promise ? await context.params : context.params) : undefined;

      return handler({ request, user, token, params });
    } catch (error: any) {
      // All errors, including auth errors, are now piped through the central handler
      return handleApiError(error);
    }
  };
};"}

{"file_path": "UNIFIED_AUTHENTICATION_GUIDE.md", "initial_content": "# Unified Authentication Guide

## Overview

This guide documents the **unified authentication method** for all API routes in the Arkan platform. As of this update, all API routes use a single, consistent authentication pattern using the `withAuth` helper from `@/lib/utils/api-utils`.

## Why Unified Authentication?

Previously, the codebase had **three different authentication methods**:
1. ❌ Manual inline authentication with `verifyUser()`/`getUserIdFromRequest()`
2. ❌ `withAuth` from `auth-middleware.ts`
3. ✅ **`withAuth` from `api-utils.ts`** (Now the single standard)

Having multiple authentication methods led to:
- **Inconsistent security practices**
- **Duplicate code maintenance**
- **Confusion for developers**
- **Harder to audit and update**

## The Unified Authentication Method

### Location
```typescript
import { withAuth, handleApiError, createApiResponse } from '@/lib/utils/api-utils';
```

### How It Works

The `withAuth` higher-order function:
1. ✅ Extracts the Bearer token from the `Authorization` header
2. ✅ Verifies the Firebase ID token using `adminAuth.verifyIdToken()`
3. ✅ Fetches the user profile from the database
4. ✅ Checks admin permissions if `requireAdmin: true` is specified
5. ✅ Handles Next.js 15 async params automatically
6. ✅ Provides standardized error handling

### Basic Usage

#### Standard Authenticated Route
```typescript
import { withAuth, handleApiError, createApiResponse } from '@/lib/utils/api-utils';

export const GET = withAuth(async ({ request, user }) => {
  try {
    // Your logic here - user is already authenticated
    const data = await fetchUserData(user.id);
    return createApiResponse(data, 200);
  } catch (error) {
    return handleApiError(error);
  }
});
```

#### Admin-Only Route
```typescript
import { withAuth, handleApiError, createApiResponse } from '@/lib/utils/api-utils';

export const POST = withAuth(async ({ request, user }) => {
  try {
    // Only admins can access this route
    const body = await request.json();
    const result = await performAdminAction(body);
    return createApiResponse(result, 200);
  } catch (error) {
    return handleApiError(error);
  }
}, { requireAdmin: true });
```

#### Route with Dynamic Parameters
```typescript
import { withAuth, handleApiError, createApiResponse } from '@/lib/utils/api-utils';

export const PUT = withAuth(async ({ request, user, params }) => {
  try {
    // params are automatically resolved (Next.js 15 async params support)
    const { id } = params;
    const body = await request.json();
    const updated = await updateResource(id, body, user.id);
    return createApiResponse(updated, 200);
  } catch (error) {
    return handleApiError(error);
  }
});
```

### AuthContext Interface

When using `withAuth`, your handler receives an `AuthContext` object:

```typescript
interface AuthContext {
  request: NextRequest;           // The original Next.js request object
  user: any;                       // The authenticated user profile from database
  token: string;                   // The verified Firebase ID token
  params?: { [key: string]: string }; // Route parameters (if any)
}
```

### User Object Properties

The `user` object contains:
- `id` - User's unique identifier (Firebase UID)
- `email` - User's email address
- `role` - User's role (`'admin'` or `'user'`)
- `displayName` - User's display name
- `credits` - User's available credits
- Other profile fields from the database

## Migration Examples

### Before (Manual Authentication)
```typescript
// ❌ Old way - manual inline authentication
import { NextResponse } from 'next/server';
import { adminAuth } from '@/lib/firebase/server-init';

async function verifyUser(request: Request) {
    let authorization = request.headers.get('Authorization');
    if (!authorization?.startsWith('Bearer ')) {
        return { authorized: false, message: 'Unauthorized', userId: null };
    }
    let token = authorization.substring(7);
    try {
        let decodedToken = await adminAuth.verifyIdToken(token, true);
        return { authorized: true, userId: decodedToken.uid };
    } catch (error) {
        return { authorized: false, message: 'Unauthorized', userId: null };
    }
}

export async function GET(request: Request) {
    let userCheck = await verifyUser(request);
    if (!userCheck.authorized || !userCheck.userId) {
        return NextResponse.json({ message: userCheck.message }, { status: 401 });
    }

    try {
        // Your logic here
        return NextResponse.json({ data: 'result' }, { status: 200 });
    } catch (error) {
        return NextResponse.json({ message: 'Error' }, { status: 500 });
    }
}
```

### After (Unified Authentication)
```typescript
// ✅ New way - unified withAuth
import { withAuth, handleApiError, createApiResponse } from '@/lib/utils/api-utils';

export const GET = withAuth(async ({ user }) => {
    try {
        // Your logic here - user is already authenticated
        return createApiResponse({ data: 'result' }, 200);
    } catch (error) {
        return handleApiError(error);
    }
});
```

## Authentication Flow

```
1. Client Request with Authorization Header
   ↓
2. withAuth extracts Bearer token
   ↓
3. Firebase Admin verifies token
   ↓
4. User profile fetched from database
   ↓
5. Admin check (if requireAdmin: true)
   ↓
6. Handler executes with authenticated user
   ↓
7. Response returned to client
```

## Error Responses

The unified authentication automatically handles these error cases:

### 401 Unauthorized - Missing Token
```json
{
  "message": "Unauthorized: Missing token"
}
```

### 401 Unauthorized - Invalid Token
```json
{
  "message": "Unauthorized: Invalid token"
}
```

### 403 Forbidden - User Not Found
```json
{
  "message": "Forbidden: User profile not found"
}
```

### 403 Forbidden - Admin Required
```json
{
  "message": "Forbidden: Admin access required"
}
```

## Best Practices

### ✅ DO
- Always use `withAuth` for authenticated routes
- Use `handleApiError` for consistent error handling
- Use `createApiResponse` for success responses
- Specify `{ requireAdmin: true }` for admin-only routes
- Access user data via the `user` object in context

### ❌ DON'T
- Don't create custom authentication functions
- Don't manually parse Authorization headers
- Don't manually verify Firebase tokens
- Don't use `NextResponse.json()` directly (use `createApiResponse` instead)
- Don't duplicate authentication logic

## Testing Authentication

### Valid Request Example
```bash
curl -X GET https://your-domain.com/api/stats \
  -H "Authorization: Bearer YOUR_FIREBASE_ID_TOKEN"
```

### Testing Admin Routes
```bash
curl -X POST https://your-domain.com/api/admin/users \
  -H "Authorization: Bearer ADMIN_FIREBASE_ID_TOKEN" \
  -H "Content-Type: application/json" \
  -d '{"email": "newuser@example.com"}'
```

## File Structure

```
src/
├── lib/
│   ├── utils/
│   │   └── api-utils.ts          # ✅ Unified authentication (withAuth)
│   └── middleware/
│       └── auth-middleware.ts     # ⚠️  Legacy - not used in API routes
├── app/
│   └── api/
│       ├── stats/
│       │   └── route.ts          # Uses withAuth
│       ├── notifications/
│       │   ├── route.ts          # Uses withAuth
│       │   ├── mark-as-read/
│       │   │   └── route.ts      # Uses withAuth
│       │   └── clear/
│       │       └── route.ts      # Uses withAuth
│       └── admin/
│           └── users/
│               └── route.ts      # Uses withAuth with requireAdmin
```

## Migration Summary

The following API routes were migrated to use the unified authentication:

### ✅ Migrated Routes
- `/api/stats` - User statistics endpoint
- `/api/notifications` - Fetch notifications (deprecated, uses RTDB now)
- `/api/notifications/mark-as-read` - Mark notifications as read
- `/api/notifications/clear` - Clear notifications

### Already Using Unified Auth
All other API routes in the following directories were already using `withAuth`:
- `/api/admin/*` - All admin routes
- `/api/agents/*` - Agent management
- `/api/projects/*` - Project management
- `/api/transactions/*` - Transaction history
- `/api/users/*` - User management
- `/api/writing-tools/*` - Writing tools
- `/api/generate/*` - Generation endpoints
- `/api/templates/*` - Template management

## Next.js 15 Compatibility

The unified `withAuth` function fully supports Next.js 15's async params pattern:

```typescript
// Next.js 15 passes params as a Promise
export const GET = withAuth(async ({ params }) => {
  // params are automatically resolved (no need to await)
  const { id } = params; // Works seamlessly
  // ...
});
```

## Security Considerations

### Token Verification
- Tokens are verified with `checkRevoked: true` to ensure revoked tokens are rejected
- Firebase Admin SDK handles token expiration automatically
- Invalid signatures are rejected

### User Profile Validation
- User profile must exist in the database
- Deleted or suspended users will fail authentication

### Admin Authorization
- Admin status is checked via the `role` field in user profile
- Only users with `role === 'admin'` can access admin routes

### Rate Limiting
While not implemented in `withAuth`, consider adding rate limiting for production:
```typescript
// Future enhancement
import { requireRateLimit } from '@/lib/middleware/auth-middleware';
```

## Troubleshooting

### "Unauthorized: Missing token"
- Ensure `Authorization` header is present
- Format must be: `Authorization: Bearer <token>`
- Check that the token is not empty

### "Unauthorized: Invalid token"
- Token may be expired (Firebase tokens expire after 1 hour)
- Token may be revoked
- Token may be from wrong Firebase project
- Refresh the token on the client side

### "Forbidden: User profile not found"
- User exists in Firebase Auth but not in Firestore
- User may have been deleted from database
- Ensure user profile is created during signup

### "Forbidden: Admin access required"
- User role is not 'admin'
- Check user profile in database
- Update role using admin functions

