      expect(firebaseConfig).toBeDefined();
      expect(firebaseConfig).toHaveProperty('apiKey');
      expect(firebaseConfig).toHaveProperty('authDomain');
      expect(firebaseConfig).toHaveProperty('projectId');
    });

    it('should export firebaseAdminConfig from @/lib/config', () => {
      const { firebaseAdminConfig } = require('@/lib/config');

      expect(firebaseAdminConfig).toBeDefined();
      expect(firebaseAdminConfig).toHaveProperty('databaseURL');
      expect(firebaseAdminConfig).toHaveProperty('storageBucket');
    });

    it('should export firebaseMessagingConfig from @/lib/config', () => {
      const { firebaseMessagingConfig } = require('@/lib/config');

      expect(firebaseMessagingConfig).toBeDefined();
      expect(firebaseMessagingConfig).toHaveProperty('vapidKey');
    });
  });

  describe('Client Initialization', () => {
    it('should export Firebase client instances', () => {
      const { app, auth, db, rtdb } = require('@/lib/firebase/client-init');

      expect(app).toBeDefined();
      expect(auth).toBeDefined();
      expect(db).toBeDefined();
      expect(rtdb).toBeDefined();
    });
  });

  describe('Server Initialization', () => {
