   0 /**
   1  * Flow Management API
   2  * 
   3  * GET /api/admin/flows - List all flows
   4  * POST /api/admin/flows - Create new flow
   5  */
   6 
   7 import { NextRequest, NextResponse } from 'next/server';
   8 import { flowConfigService } from '@/services/flow-config-service';
   9 import { FlowStatus } from '@/lib/models/flow-config';
  10 import { withAuth } from '@/lib/utils/api-utils';
  11 
  12 /**
  13  * GET /api/admin/flows
  14  * List all flows with optional filters
  15  */
  16 export const GET = withAuth(async ({ request, user }) => {
  17   try {
  18     // Get query parameters
  19     const searchParams = request.nextUrl.searchParams;
  20     const status = searchParams.get('status') as FlowStatus | null;
  21     const category = searchParams.get('category');
  22     const tags = searchParams.get('tags')?.split(',');
  23     const limit = searchParams.get('limit') ? parseInt(searchParams.get('limit')!) : undefined;
  24 
  25     // Build filters
  26     const filters: any = {};
  27     if (status) filters.status = status;
  28     if (category) filters.category = category;
  29     if (tags) filters.tags = tags;
  30     if (limit) filters.limit = limit;
  31 
  32     // Get flows
  33     const flows = await flowConfigService.listFlows(filters);
  34 
  35     return NextResponse.json({
  36       success: true,
  37       flows,
  38       total: flows.length,
  39     });
  40   } catch (error) {
  41     console.error('Error listing flows:', error);
  42     return NextResponse.json(
  43       {
  44         success: false,
  45         error: error instanceof Error ? error.message : 'Failed to list flows',
  46       },
  47       { status: 500 }
  48     );
  49   }
  50 }, { requireAdmin: true });
  51 
  52 /**
  53  * POST /api/admin/flows
  54  * Create a new flow
  55  */
  56 export const POST = withAuth(async ({ request, user }) => {
  57   try {
  58     const body = await request.json();
  59 
  60     // Create flow with authenticated admin user ID
  61     const flow = await flowConfigService.createFlow(body, user.id);
  62 
  63     return NextResponse.json({
  64       success: true,
  65       flow,
  66       message: 'Flow created successfully',
  67     }, { status: 201 });
  68   } catch (error) {
  69     console.error('Error creating flow:', error);
  70     
  71     const statusCode = error instanceof Error && error.name === 'ValidationError' 
  72       ? 400 
  73       : 500;
  74 
  75     return NextResponse.json(
  76       {
  77         success: false,
  78         error: error instanceof Error ? error.message : 'Failed to create flow',
  79       },
  80       { status: statusCode }
  81     );
  82   }
  83 }, { requireAdmin: true });
