 333 export function renderTemplate(
 334   template: string,
 335   variables: Record<string, any>
 336 ): string {
 337   let rendered = template;
 338   
 339   // Replace variables
 340   rendered = rendered.replace(TEMPLATE_PATTERNS.VARIABLE, (match, varName) => {
 341     const name = varName.trim();
 342     const value = variables[name];
 343     
 344     if (value === undefined) {
 345       console.warn(`Variable '${name}' not found in context`);
 346       return match; // Keep placeholder
 347     }
 348     
 349     return String(value);
 350   });
 351   
 352   // Handle conditionals
 353   rendered = rendered.replace(TEMPLATE_PATTERNS.CONDITIONAL, (match, condition, content) => {
 354     try {
 355       const conditionResult = evaluateCondition(condition.trim(), variables);
 356       return conditionResult ? content : '';
 357     } catch (error) {
 358       console.error('Error evaluating condition:', error);
 359       return match;
 360     }
 361   });
 362   
 363   // Handle loops
 364   rendered = rendered.replace(TEMPLATE_PATTERNS.LOOP, (match, itemsVar, content) => {
 365     const items = variables[itemsVar.trim()];
 366     
 367     if (!Array.isArray(items)) {
 368       console.warn(`Variable '${itemsVar}' is not an array`);
 369       return match;
 370     }
 371     
 372     return items.map(item => {
 373       return content.replace(/\{\{this\}\}/g, String(item));
 374     }).join('\n');
 375   });
 376   
 377   return rendered;
