 461 function validateVariableValue(value: any, variable: PromptVariable): string[] {
 462   const errors: string[] = [];
 463   const validation = variable.validation;
 464   
 465   if (!validation) return errors;
 466   
 467   // String validation
 468   if (typeof value === 'string') {
 469     if (validation.minLength && value.length < validation.minLength) {
 470       errors.push(`${variable.name} must be at least ${validation.minLength} characters`);
 471     }
 472     if (validation.maxLength && value.length > validation.maxLength) {
 473       errors.push(`${variable.name} must be at most ${validation.maxLength} characters`);
 474     }
 475     if (validation.pattern) {
 476       const regex = new RegExp(validation.pattern);
 477       if (!regex.test(value)) {
 478         errors.push(validation.message || `${variable.name} does not match required pattern`);
 479       }
 480     }
 481   }
 482   
 483   // Number validation
 484   if (typeof value === 'number') {
 485     if (validation.min !== undefined && value < validation.min) {
 486       errors.push(`${variable.name} must be at least ${validation.min}`);
 487     }
 488     if (validation.max !== undefined && value > validation.max) {
 489       errors.push(`${variable.name} must be at most ${validation.max}`);
 490     }
 491     if (validation.integer && !Number.isInteger(value)) {
 492       errors.push(`${variable.name} must be an integer`);
 493     }
 494   }
 495   
 496   // Array validation
 497   if (Array.isArray(value)) {
 498     if (validation.minItems && value.length < validation.minItems) {
 499       errors.push(`${variable.name} must have at least ${validation.minItems} items`);
 500     }
 501     if (validation.maxItems && value.length > validation.maxItems) {
 502       errors.push(`${variable.name} must have at most ${validation.maxItems} items`);
 503     }
 504     if (validation.uniqueItems) {
 505       const unique = new Set(value);
 506       if (unique.size !== value.length) {
 507         errors.push(`${variable.name} must have unique items`);
 508       }
 509     }
 510   }
 511   
 512   // Enum validation
 513   if (validation.enum && !validation.enum.includes(value)) {
 514     errors.push(`${variable.name} must be one of: ${validation.enum.join(', ')}`);
 515   }
 516   
 517   return errors;
