 144    */
 145   async registerTool(
 146     tool: Partial<ToolConfiguration>,
 147     userId: string
 148   ): Promise<ToolConfiguration> {
 149     try {
 150       // Validate tool configuration
 151       const errors = validateToolConfiguration(tool);
 152       if (errors.length > 0) {
 153         throw new ValidationError('Tool validation failed', errors);
 154       }
 155 
 156       // Check if tool with same name already exists
 157       const existing = await this.getToolByName(tool.name!);
 158       if (existing) {
 159         throw new ToolAlreadyExistsError(tool.name!);
 160       }
 161 
 162       // Create tool configuration with defaults
 163       const toolConfig = createToolConfiguration({
 164         ...tool,
 165         createdBy: userId,
 166       });
 167 
 168       // Create new document
 169       const docRef = doc(this.toolsCollection);
 170       const now = Timestamp.now();
 171 
 172       const toolData: ToolConfiguration = {
 173         ...toolConfig,
 174         createdAt: now,
 175         updatedAt: now,
 176       };
 177 
 178       await setDoc(docRef, toolData);
 179 
 180       return toolData;
 181     } catch (error) {
 182       console.error('Error registering tool:', error);
 183       if (error instanceof ToolServiceError) {
 184         throw error;
 185       }
 186       throw new ToolServiceError('Failed to register tool', error);
 187     }
 188   }
