 190   /**
 191    * Update tool configuration
 192    */
 193   async updateTool(
 194     toolName: string,
 195     updates: Partial<ToolConfiguration>,
 196     userId: string
 197   ): Promise<ToolConfiguration> {
 198     try {
 199       // Cannot update built-in tools
 200       if (this.builtinTools.has(toolName)) {
 201         throw new ToolServiceError('Cannot update built-in tool');
 202       }
 203 
 204       const existing = await this.getToolByName(toolName);
 205 
 206       if (!existing) {
 207         throw new ToolNotFoundError(toolName);
 208       }
 209 
 210       // Validate updated configuration
 211       const updatedTool = { ...existing, ...updates };
 212       const errors = validateToolConfiguration(updatedTool);
 213       if (errors.length > 0) {
 214         throw new ValidationError('Tool validation failed', errors);
 215       }
 216 
 217       // Find document by name
 218       const q = query(this.toolsCollection, where('name', '==', toolName));
 219       const snapshot = await getDocs(q);
 220 
 221       if (snapshot.empty) {
 222         throw new ToolNotFoundError(toolName);
 223       }
 224 
 225       const docRef = doc(this.toolsCollection, snapshot.docs[0].id);
 226 
 227       await updateDoc(docRef, {
 228         ...updates,
 229         updatedAt: Timestamp.now(),
 230       });
 231 
 232       return { ...existing, ...updates, updatedAt: Timestamp.now() };
 233     } catch (error) {
 234       console.error('Error updating tool:', error);
