 242   /**
 243    * Execute a tool
 244    */
 245   async executeTool(
 246     toolName: string,
 247     parameters: Record<string, any>,
 248     timeoutMs?: number
 249   ): Promise<any> {
 250     try {
 251       const tool = await this.getToolByName(toolName);
 252 
 253       if (!tool) {
 254         throw new ToolNotFoundError(toolName);
 255       }
 256 
 257       if (tool.status !== 'active') {
 258         throw new ToolServiceError(`Tool is not active: ${toolName} (status: ${tool.status})`);
 259       }
 260 
 261       const timeout = timeoutMs || tool.timeout || 30000;
 262 
 263       // Execute based on tool type
 264       switch (tool.type) {
 265         case 'builtin':
 266           return await this.executeBuiltinTool(toolName, parameters, timeout);
 267 
 268         case 'custom':
 269           return await this.executeCustomTool(tool, parameters, timeout);
 270 
 271         case 'external':
 272           return await this.executeExternalTool(tool, parameters, timeout);
 273 
 274         default:
 275           throw new ToolServiceError(`Unknown tool type: ${tool.type}`);
 276       }
 277     } catch (error) {
 278       console.error('Error executing tool:', error);
 279       if (error instanceof ToolServiceError) {
 280         throw error;
 281       }
 282       throw new ModelToolExecutionError(toolName, 'Tool execution failed', error as Error);
 283     }
