 321   /**
 322    * Execute external tool (HTTP API)
 323    */
 324   private async executeExternalTool(
 325     tool: ToolConfiguration,
 326     parameters: Record<string, any>,
 327     timeout: number
 328   ): Promise<any> {
 329     try {
 330       const url = tool.handler;
 331 
 332       // Parse as ExternalToolConfig if available
 333       const externalConfig: ExternalToolConfig = {
 334         name: tool.name,
 335         endpoint: url,
 336         method: 'POST', // Default to POST
 337         authType: 'none',
 338       };
 339 
 340       const headers: Record<string, string> = {
 341         'Content-Type': 'application/json',
 342         ...externalConfig.headers,
 343       };
 344 
 345       // Add authentication if configured
 346       if (externalConfig.authType === 'bearer' && externalConfig.authConfig?.token) {
 347         headers['Authorization'] = `Bearer ${externalConfig.authConfig.token}`;
 348       } else if (externalConfig.authType === 'api-key' && externalConfig.authConfig?.apiKey) {
 349         headers['X-API-Key'] = externalConfig.authConfig.apiKey;
 350       }
 351 
 352       const controller = new AbortController();
 353       const timeoutId = setTimeout(() => controller.abort(), timeout);
 354 
 355       const response = await fetch(url, {
 356         method: externalConfig.method,
 357         headers,
 358         body: JSON.stringify(parameters),
 359         signal: controller.signal,
 360       });
 361 
 362       clearTimeout(timeoutId);
 363 
 364       if (!response.ok) {
 365         throw new ToolServiceError(`External tool returned ${response.status}: ${response.statusText}`);
 366       }
 367 
 368       const result = await response.json();
 369 
 370       // Extract result based on response mapping if configured
 371       return result;
 372     } catch (error) {
 373       if (error instanceof Error && error.name === 'AbortError') {
 374         throw new ModelToolTimeoutError(tool.name, timeout);
 375       }
 376       throw error;
 377     }
 378   }
