{"file_path": "src/hooks/admin/use-flow-validation.ts", "initial_content": "/**
 * Flow Validation Hook
 * 
 * Provides real-time validation for flow configurations
 * with detailed error messages and suggestions.
 */

import { useState, useEffect, useCallback } from 'react';
import { FlowConfiguration, FlowStep, validateFlowConfiguration } from '@/lib/models/flow-config';

export interface ValidationError {
  field: string;
  message: string;
  suggestion?: string;
  severity: 'error' | 'warning' | 'info';
}

export interface ValidationResult {
  isValid: boolean;
  errors: ValidationError[];
  warnings: ValidationError[];
}

export function useFlowValidation(flow: Partial<FlowConfiguration>) {
  const [validationResult, setValidationResult] = useState<ValidationResult>({
    isValid: true,
    errors: [],
    warnings: [],
  });

  const validateFlow = useCallback(() => {
    const errors: ValidationError[] = [];
    const warnings: ValidationError[] = [];

    // Basic validation
    const basicErrors = validateFlowConfiguration(flow);
    basicErrors.forEach(error => {
      errors.push({
        field: 'general',
        message: error,
        severity: 'error',
      });
    });

    // Name validation
    if (flow.name) {
      if (!/^[a-z0-9-]+$/.test(flow.name)) {
        errors.push({
          field: 'name',
          message: 'Flow name must contain only lowercase letters, numbers, and hyphens',
          suggestion: 'Example: my-flow-name',
          severity: 'error',
        });
      }
      if (flow.name.length > 50) {
        errors.push({
          field: 'name',
          message: 'Flow name is too long (max 50 characters)',
          severity: 'error',
        });
      }
    }

    // Display name validation
    if (flow.displayName && flow.displayName.length > 100) {
      errors.push({
        field: 'displayName',
        message: 'Display name is too long (max 100 characters)',
        severity: 'error',
      });
    }

    // Description validation
    if (flow.description && flow.description.length > 500) {
      warnings.push({
        field: 'description',
        message: 'Description is quite long. Consider being more concise.',
        severity: 'warning',
      });
    }

    // Steps validation
    if (flow.steps) {
      if (flow.steps.length === 0) {
        warnings.push({
          field: 'steps',
          message: 'Flow has no steps. Add steps to make it functional.',
          suggestion: 'Use the step library to add steps',
          severity: 'warning',
        });
      }

      if (flow.steps.length > 20) {
        warnings.push({
          field: 'steps',
          message: 'Flow has many steps. Consider breaking it into smaller flows.',
          severity: 'warning',
        });
      }

      // Validate step IDs are unique
      const stepIds = flow.steps.map(s => s.id);
      const duplicates = stepIds.filter((id, index) => stepIds.indexOf(id) !== index);
      if (duplicates.length > 0) {
        errors.push({
          field: 'steps',
          message: `Duplicate step IDs found: ${[...new Set(duplicates)].join(', ')}`,
          suggestion: 'Each step must have a unique ID',
          severity: 'error',
        });
      }

      // Validate individual steps
      flow.steps.forEach((step, index) => {
        if (!step.name) {
          errors.push({
            field: `steps[${index}].name`,
            message: `Step ${index + 1}: Name is required`,
            severity: 'error',
          });
        }

        if (!step.type) {
          errors.push({
            field: `steps[${index}].type`,
            message: `Step ${index + 1}: Type is required`,
            severity: 'error',
          });
        }
      });
    }

    // Settings validation
    if (flow.settings) {
      if (flow.settings.timeout && flow.settings.timeout > 600000) {
        warnings.push({
          field: 'settings.timeout',
          message: 'Timeout is very high (>10 minutes). This may cause issues.',
          severity: 'warning',
        });
      }

      if (flow.settings.rateLimitPerMinute && flow.settings.rateLimitPerMinute > 1000) {
        warnings.push({
          field: 'settings.rateLimitPerMinute',
          message: 'Rate limit is very high. Consider reducing it.',
          severity: 'warning',
        });
      }
    }

    setValidationResult({
      isValid: errors.length === 0,
      errors,
      warnings,
    });
  }, [flow]);

  useEffect(() => {
    validateFlow();
  }, [validateFlow]);

  return {
    ...validationResult,
    validate: validateFlow,
    hasErrors: validationResult.errors.length > 0,
    hasWarnings: validationResult.warnings.length > 0,
  };
}

/**
 * Hook for validating individual steps
 */
export function useStepValidation(step: Partial<FlowStep>) {
  const [errors, setErrors] = useState<ValidationError[]>([]);

  useEffect(() => {
    const newErrors: ValidationError[] = [];

    if (!step.id) {
      newErrors.push({
        field: 'id',
        message: 'Step ID is required',
        severity: 'error',
      });
    }

    if (!step.name) {
      newErrors.push({
        field: 'name',
        message: 'Step name is required',
        severity: 'error',
      });
    }

    if (!step.type) {
      newErrors.push({
        field: 'type',
        message: 'Step type is required',
        severity: 'error',
      });
    }

    setErrors(newErrors);
  }, [step]);

  return {
    errors,
    isValid: errors.length === 0,
  };
}
"}

