{"file_path": "src/components/admin/flow-builder/ValidationPanel.tsx", "initial_content": "/**
 * Validation Panel Component
 * 
 * Displays real-time validation errors and warnings for flows.
 */

'use client';

import React from 'react';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Badge } from '@/components/ui/badge';
import { ScrollArea } from '@/components/ui/scroll-area';
import { AlertCircle, AlertTriangle, Info, CheckCircle2 } from 'lucide-react';
import { ValidationError } from '@/hooks/admin/use-flow-validation';

interface ValidationPanelProps {
  errors: ValidationError[];
  warnings: ValidationError[];
  className?: string;
}

export function ValidationPanel({ errors, warnings, className }: ValidationPanelProps) {
  const hasErrors = errors.length > 0;
  const hasWarnings = warnings.length > 0;
  const isValid = !hasErrors && !hasWarnings;

  if (isValid) {
    return (
      <div className={className}>
        <Alert className="border-green-500 bg-green-50 dark:bg-green-950">
          <CheckCircle2 className="h-4 w-4 text-green-600" />
          <AlertTitle className="text-green-800 dark:text-green-200">
            All Good!
          </AlertTitle>
          <AlertDescription className="text-green-700 dark:text-green-300">
            Your flow configuration is valid and ready to save.
          </AlertDescription>
        </Alert>
      </div>
    );
  }

  return (
    <div className={className}>
      <ScrollArea className="h-full">
        <div className="space-y-3">
          {/* Errors */}
          {hasErrors && (
            <div className="space-y-2">
              <div className="flex items-center gap-2">
                <AlertCircle className="h-4 w-4 text-red-600" />
                <h3 className="font-semibold text-sm">
                  Errors ({errors.length})
                </h3>
              </div>
              {errors.map((error, index) => (
                <ValidationItem key={`error-${index}`} validation={error} />
              ))}
            </div>
          )}

          {/* Warnings */}
          {hasWarnings && (
            <div className="space-y-2">
              <div className="flex items-center gap-2">
                <AlertTriangle className="h-4 w-4 text-yellow-600" />
                <h3 className="font-semibold text-sm">
                  Warnings ({warnings.length})
                </h3>
              </div>
              {warnings.map((warning, index) => (
                <ValidationItem key={`warning-${index}`} validation={warning} />
              ))}
            </div>
          )}
        </div>
      </ScrollArea>
    </div>
  );
}

function ValidationItem({ validation }: { validation: ValidationError }) {
  const Icon = validation.severity === 'error' 
    ? AlertCircle 
    : validation.severity === 'warning' 
    ? AlertTriangle 
    : Info;

  const colorClasses = {
    error: 'border-red-200 bg-red-50 dark:bg-red-950/50',
    warning: 'border-yellow-200 bg-yellow-50 dark:bg-yellow-950/50',
    info: 'border-blue-200 bg-blue-50 dark:bg-blue-950/50',
  };

  const textClasses = {
    error: 'text-red-800 dark:text-red-200',
    warning: 'text-yellow-800 dark:text-yellow-200',
    info: 'text-blue-800 dark:text-blue-200',
  };

  const iconClasses = {
    error: 'text-red-600',
    warning: 'text-yellow-600',
    info: 'text-blue-600',
  };

  return (
    <Alert className={colorClasses[validation.severity]}>
      <Icon className={`h-4 w-4 ${iconClasses[validation.severity]}`} />
      <div className="flex-1">
        <AlertTitle className={`text-sm ${textClasses[validation.severity]}`}>
          {validation.field !== 'general' && (
            <Badge variant="outline" className="mr-2">
              {validation.field}
            </Badge>
          )}
          {validation.message}
        </AlertTitle>
        {validation.suggestion && (
          <AlertDescription className={`text-xs mt-1 ${textClasses[validation.severity]}`}>
            💡 {validation.suggestion}
          </AlertDescription>
        )}
      </div>
    </Alert>
  );
}

/**
 * Inline validation indicator for form fields
 */
interface FieldValidationProps {
  fieldName: string;
  errors: ValidationError[];
  warnings: ValidationError[];
}

export function FieldValidation({ fieldName, errors, warnings }: FieldValidationProps) {
  const fieldErrors = errors.filter(e => e.field === fieldName);
  const fieldWarnings = warnings.filter(w => w.field === fieldName);

  if (fieldErrors.length === 0 && fieldWarnings.length === 0) {
    return null;
  }

  return (
    <div className="mt-1 space-y-1">
      {fieldErrors.map((error, index) => (
        <div key={`error-${index}`} className="flex items-start gap-2 text-sm text-red-600">
          <AlertCircle className="h-4 w-4 mt-0.5 flex-shrink-0" />
          <div>
            <p>{error.message}</p>
            {error.suggestion && (
              <p className="text-xs text-red-500 mt-1">💡 {error.suggestion}</p>
            )}
          </div>
        </div>
      ))}
      {fieldWarnings.map((warning, index) => (
        <div key={`warning-${index}`} className="flex items-start gap-2 text-sm text-yellow-600">
          <AlertTriangle className="h-4 w-4 mt-0.5 flex-shrink-0" />
          <div>
            <p>{warning.message}</p>
            {warning.suggestion && (
              <p className="text-xs text-yellow-500 mt-1">💡 {warning.suggestion}</p>
            )}
          </div>
        </div>
      ))}
    </div>
  );
}
"}

