  category: string;
  steps: Partial<FlowStep>[];
}

export const FLOW_TEMPLATES: FlowTemplate[] = [
  {
    id: 'simple-rag',
    name: 'Simple RAG Flow',
    description: 'Basic Retrieval-Augmented Generation flow',
    category: 'RAG',
    steps: [
      {
        id: 'step-1',
        type: 'RETRIEVE',
        name: 'retrieve-context',
        description: 'Retrieve relevant documents',
        config: {
          type: 'RETRIEVE',
          retrieverName: 'default',
          query: '{{userQuery}}',
          topK: 5,
        },
        inputSchema: {},
        outputSchema: {},
      },
      {
        id: 'step-2',
        type: 'GENERATE',
        name: 'generate-response',
        description: 'Generate response with context',
        config: {
          type: 'GENERATE',
          promptId: '',
          temperature: 0.7,
        },
        inputSchema: {},
        outputSchema: {},
      },
    ],
  },

  {
    id: 'research-assistant',
    name: 'Research Assistant',
    description: 'Search web, analyze, and generate report',
    category: 'Research',
    steps: [
      {
        id: 'step-1',
        type: 'TOOL',
        name: 'search-web',
        description: 'Search for information',
        config: {
          type: 'TOOL',
          toolName: 'google-search',
          parameters: {},
        },
        inputSchema: {},
        outputSchema: {},
      },
      {
        id: 'step-2',
        type: 'GENERATE',
        name: 'analyze-results',
        description: 'Analyze search results',
        config: {
          type: 'GENERATE',
          promptId: '',
        },
        inputSchema: {},
        outputSchema: {},
      },
      {
        id: 'step-3',
        type: 'FORMAT',
        name: 'format-report',
        description: 'Format as report',
        config: {
          type: 'FORMAT',
          outputFormat: 'markdown',
        },
        inputSchema: {},
        outputSchema: {},
      },
    ],
  },
];

/**
 * Get step template by ID
 */
export function getStepTemplate(templateId: string): StepTemplate | undefined {
  return STEP_TEMPLATES.find(t => t.id === templateId);
}

/**
 * Get flow template by ID
 */
export function getFlowTemplate(templateId: string): FlowTemplate | undefined {
  return FLOW_TEMPLATES.find(t => t.id === templateId);
}

/**
 * Create a step from template with unique ID
 */
export function createStepFromTemplate(templateId: string, index: number): FlowStep | null {
  const template = getStepTemplate(templateId);
  if (!template) return null;

  return {
    ...template.template,
    id: `step-${Date.now()}-${index}`,
    name: template.template.name || `step-${index}`,
  } as FlowStep;
}
"}

